  selectedCar: CarDto | null = null;
  ratingValue: number | null = null;

  private readonly api = inject(ApiService);
  private readonly messages = inject(MessageService);

  ngOnInit(): void {
    this.api.getCars().subscribe({
      next: (cars) => {
        this.selectedCar = cars[0] ?? null;
        this.cars.set(cars);
      },
      error: () => {
        this.messages.error('Could not load cars');
        this.closed.emit();
      },
    });
  }

  carText(car: CarDto): string {
    return carLabel(car);
  }

  save(): void {
    const dto: RatingDto = { id: null, rating: this.ratingValue, car: this.selectedCar };
    this.api.saveRating(dto).subscribe({
      next: (saved) => {
        this.messages.success('Rating saved');
        this.saved.emit(saved);
        this.closed.emit();
      },
      error: () => this.messages.error('Could not save the rating'),
    });
  }
}
