import { Injectable, signal } from '@angular/core';

export type MessageStyle = 'success' | 'error';

export interface AppMessage {
  id: number;
  text: string;
  style: MessageStyle;
}

/** Replaces GWT's DisplayMessageEvent. Messages auto-close after 5 s, like MessageCloseDelay.DEFAULT. */
@Injectable({ providedIn: 'root' })
export class MessageService {
  private nextId = 1;
  readonly messages = signal<AppMessage[]>([]);

  success(text: string): void {
    this.add(text, 'success');
  }

  error(text: string): void {
    this.add(text, 'error');
  }

  close(id: number): void {
    this.messages.update((list) => list.filter((m) => m.id !== id));
  }

  private add(text: string, style: MessageStyle): void {
    const id = this.nextId++;
    this.messages.update((list) => [...list, { id, text, style }]);
    setTimeout(() => this.close(id), 5000);
  }
}
